void mainImage(out vec4 fragColor, in vec2 fragCoord)

{

    // Screen resolution and normalized coordinates

    vec2 uv = fragCoord / iResolution.xy;

    uv = uv * 2.0 - 1.0; // Normalize coordinates to [-1, 1]

    uv.x *= iResolution.x / iResolution.y; // Correct aspect ratio

    // Rainbow gradient based on position

    vec3 rainbow = 0.5 + 0.5 * sin(vec3(uv.x, uv.y, uv.x + uv.y) + iTime * 2.0);

    // Cube effect

    float glow = 0.02 / length(uv - round(uv));

    vec3 color = rainbow + glow * vec3(1.0, 1.0, 1.0); // Add white glow

    // Final color output

    fragColor = vec4(color, 1.0);

}
